    embeddedByteLength: embeddedByteLength,
    valueNano: out.valueNano,
    valueErg: out.valueErg,
    ergoTree: out.ergoTree,
    creationHeight: out.creationHeight,
    tokens: out.tokens,
    registers: out.registers
