    if (!hVlq) return walkFail("output " + (o + 1) + "'s creation height");
    pos += hVlq.length;
    var sectionStart = pos;
    var tc = readVlqBig(bytes, pos);
    if (!tc) return walkFail("output " + (o + 1) + "'s token count");
    pos += tc.length;
