      pos += idxVlq.length;
      var amtVlq = readVlqBig(bytes, pos);
      if (!amtVlq) return walkFail("output " + (o + 1) + "'s token amount");
      pos += amtVlq.length;
      var di2 = Number(idxVlq.value);
